Method.Implementation:
Set tStatus = $$$OK Try {
$$$TRACE("In JsonToHttp Transform")
// Create the target Set pTarget = ##class(EnsLib.HTTP.GenericMessage).%New() Set tStream = "" Set tStream = ##class(%Stream.GlobalCharacter).%New() Do tStream.Write(pSource.StringValue) Do tStream.Rewind()
Do pTarget.HTTPHeaders.SetAt("application/json","content-type") Do pTarget.HTTPHeaders.SetAt(tStream.Size,"content-length") Set pTarget.Stream = ##class(%Stream.GlobalBinary).%New() Set tStatus = pTarget.Stream.CopyFrom(tStream) $$$ThrowOnError(tStatus)
// Trace some data Do tStream.Rewind() Set tStr = tStream.Read() $$$TRACE("Data string: " _ tStr)
} Catch eException { Set tStatus = eException.AsStatus() } Quit tStatus
